using System;
using System.Linq;
using System.IO;
using Touchfish;
public static partial class RuleTests {
 static void Names(){
  Check(PlayerNames.Normalize(null,0)=="玩家 1"&&PlayerNames.Normalize("  ",1)=="玩家 2","Blank names have seat-based defaults");Check(PlayerNames.Normalize("  鱼子  ",0)=="鱼子","Trim ordinary surrounding spaces");Check(PlayerNames.Normalize("名称十二个字符测试一二三",0).Length==12,"Twelve characters accepted");bool rejected=false;try{PlayerNames.Normalize(new string('x',13),0);}catch(InvalidOperationException){rejected=true;}Check(rejected,"Oversized names rejected on model boundary");foreach(string invalid in new[]{"a\nb","\nBob","a\0b"}){rejected=false;try{PlayerNames.Normalize(invalid,0);}catch(InvalidOperationException){rejected=true;}Check(rejected,"Control characters cannot create extra history lines");}
  var g=new MatchEngine(catalog,matchRules.TrainingDeck("MAGE"),matchRules.TrainingDeck("WARRIOR"),42,firstName:"鱼子",secondName:"朋友");Check(g.PlayerLabel(0)=="鱼子"&&g.PlayerLabel(1)=="朋友","Names bound to seats");Check(g.Log.First().Contains("鱼子")&&g.Log.First().Contains("朋友")&&g.Log.Any(x=>x.StartsWith("鱼子 · 抽牌"))&&g.Log.Any(x=>x.StartsWith("朋友 · 抽牌")),"Names set before initial draws are recorded");g.MarkMulliganCompleteForTests();g.Players[0].Hand.Clear();g.Players[0].Mana=10;int fire=Hand(g,"CS2_029");g.Play(0,fire,new MatchTarget(1));Check(g.Log.Any(x=>x.StartsWith("鱼子 · 使用")&&x.Contains("朋友 英雄")),"Card source and hero target use named public history");g.Emote(0,HeroEmotes.Options("MAGE")[0].Value);Check(g.Log.Last().StartsWith("鱼子 ·"),"Named emote recorded without editing past logs");g.EndTurn();Check(g.Log.Last().Contains("朋友"),"Turn change records current name");var view=LanProtocol.ReadView(catalog,LanProtocol.Copy(LanProtocol.View(g,1,"names",0)));Check(view.Players[0].DisplayName=="鱼子"&&view.Players[1].DisplayName=="朋友"&&view.PlayerLabel(0)==g.PlayerLabel(0),"Names explicitly synchronized in public whitelist");Check(view.Players[0].Hand.Count==0&&view.Log.SequenceEqual(g.Log),"Name synchronization preserves hand privacy and shared history");var publicState=PublicPlayerState.From(g.Players[0]);var player=new MatchPlayer();publicState.Apply(player);Check(player.DisplayName=="鱼子","Public player copy includes display name");
  g=new MatchEngine(catalog,matchRules.TrainingDeck("MAGE"),matchRules.TrainingDeck("WARRIOR"),42,firstName:"同名",secondName:"同名");Check(g.PlayerLabel(0)=="同名（1）"&&g.PlayerLabel(1)=="同名（2）","Duplicate names remain distinguishable");var host=new LanHostGame(catalog,matchRules.TrainingDeck("MAGE"),matchRules.TrainingDeck("WARRIOR"),42,firstSeat:1,hostName:"房主",guestName:"客人");Check(host.Game.FirstSeat==1&&host.Game.Players[0].DisplayName=="房主"&&host.Game.Players[1].DisplayName=="客人","Randomized opening does not swap player identity");host.Game.ReplaceHero(0,HeroReplacementRules.JaraxxusId);Check(host.Game.PlayerLabel(0)=="房主","Hero replacement preserves player name");var snapshot=LanProtocol.View(host.Game,1,"bad-name",0);snapshot.Players[0].Public.DisplayName="bad\nname";rejected=false;try{LanProtocol.ReadView(catalog,snapshot);}catch(InvalidOperationException){rejected=true;}Check(rejected,"Invalid public snapshot name rejected");
 }
}
